<?php
namespace App\Services;
use App\Models\TenantFiscalSetting;
class TenantFiscalSettingService { public const KEYS=['stock_entry','external_fuel_filling','fuel_receipt','maintenance_external_service']; public const LABELS=['stock_entry'=>'Entrada de item no estoque','external_fuel_filling'=>'Abastecimento em posto externo','fuel_receipt'=>'Recebimento de combustível no tanque','maintenance_external_service'=>'Serviços terceirizados em manutenção']; public function getCurrent(): TenantFiscalSetting { $user=auth()->user(); return TenantFiscalSetting::firstOrCreate(['tenant_id'=>$user->tenant_id,'division_id'=>session('active_division_id')],['fiscal_document_requirements'=>$this->defaults()]); } public function requirements(): array{return array_replace($this->defaults(),$this->getCurrent()->fiscal_document_requirements??[]);} public function requires(string $key): bool {return (bool)($this->requirements()[$key]??false);} public function updateRequirements(array $values): TenantFiscalSetting {$requirements=[];foreach(self::KEYS as $key)$requirements[$key]=(bool)($values[$key]??false);$setting=$this->getCurrent();$setting->update(['fiscal_document_requirements'=>$requirements]);return $setting;} public function defaults():array{return array_fill_keys(self::KEYS,false);} }
